package star.tracto.deps;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The members generated by Lombok added to the original sources (Step 43): the code of the developer is kept as it is
 * (delombok rewrites the initializers of {@code @Builder.Default} fields and moves some comments), the members marked
 * {@code @lombok.Generated} by delombok are added to their type.
 */
class LombokMembersTest {

    private static final String ORIGINAL = """
            package com.acme;

            import lombok.Builder;
            import lombok.Getter;
            import lombok.extern.slf4j.Slf4j;

            @Slf4j
            @Getter
            @Builder
            public class Status {
                @Builder.Default
                private boolean connected = false;
                private final String name;

                public String describe() {
                    if (connected) {
                        return name;
                    // } else if (other) {
                    } else {
                        return "-";
                    }
                }

                @Getter
                public static class Detail {
                    private int code;
                }
            }
            """;

    /** As delombok writes it (the code of the developer reprinted, the generated members marked). */
    private static final String DELOMBOKED = """
            package com.acme;

            public class Status {
                @java.lang.SuppressWarnings("all")
                @lombok.Generated
                private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(Status.class);
                private boolean connected;
                private final String name;

                public String describe() {
                    if (connected) {
                        return name;
                    } else // } else if (other) {
                    {
                        return "-";
                    }
                }


                public static class Detail {
                    private int code;

                    @java.lang.SuppressWarnings("all")
                    @lombok.Generated
                    public int getCode() {
                        return this.code;
                    }
                }

                @java.lang.SuppressWarnings("all")
                @lombok.Generated
                private static boolean $default$connected() {
                    return false;
                }


                @java.lang.SuppressWarnings("all")
                @lombok.Generated
                public static class StatusBuilder {
                    @java.lang.SuppressWarnings("all")
                    @lombok.Generated
                    private String name;

                    @java.lang.SuppressWarnings("all")
                    @lombok.Generated
                    public Status.StatusBuilder name(final String name) {
                        this.name = name;
                        return this;
                    }
                }

                /**
                 * The name of the status
                 */
                @java.lang.SuppressWarnings("all")
                @lombok.Generated
                public String getName() {
                    return this.name;
                }
            }
            """;

    @Test
    void theGeneratedMembersAreAddedToTheOriginal() {
        String merged = LombokMembers.merge(ORIGINAL, DELOMBOKED).orElseThrow();

        // The original, unchanged, before the closing brace of each type
        String beforeDetailEnd = ORIGINAL.substring(0, ORIGINAL.indexOf("        private int code;\n") + "        private int code;\n".length());
        assertTrue(merged.startsWith(beforeDetailEnd), merged);
        assertTrue(merged.contains("private boolean connected = false;"), merged);
        assertTrue(merged.contains("    // } else if (other) {\n        } else {"), merged);
        // The generated members, with their Javadoc, in their type
        assertTrue(merged.contains("private static final org.slf4j.Logger log"), merged);
        assertTrue(merged.contains("public static class StatusBuilder"), merged);
        assertTrue(merged.contains("/**\n     * The name of the status\n     */\n    @java.lang.SuppressWarnings(\"all\")"), merged);
        int detail = merged.indexOf("public static class Detail");
        int getCode = merged.indexOf("public int getCode()");
        int detailEnd = merged.indexOf("$default$connected");
        assertTrue(detail < getCode && getCode < detailEnd, merged);
        // Each generated member once
        assertEquals(merged.indexOf("public String getName()"), merged.lastIndexOf("public String getName()"));
    }

    @Test
    void anEnumWithoutMembersGetsTheSemicolonOfItsConstants() {
        String original = """
                package com.acme;

                @lombok.RequiredArgsConstructor
                public enum Kind {
                    A, B
                }
                """;
        String delomboked = """
                package com.acme;

                public enum Kind {
                    A, B;

                    @java.lang.SuppressWarnings("all")
                    @lombok.Generated
                    private Kind() {
                    }
                }
                """;
        String merged = LombokMembers.merge(original, delomboked).orElseThrow();
        assertTrue(merged.contains("A, B\n;"), merged);
        assertTrue(merged.contains("private Kind()"), merged);
    }

    @Test
    void aFileThatCannotBeMergedKeepsTheDelombokedCopy(@TempDir Path tempDir) throws IOException {
        Path sources = tempDir.resolve("src");
        Path copies = tempDir.resolve("delombok");
        Files.createDirectories(sources.resolve("com/acme"));
        Files.createDirectories(copies.resolve("com/acme"));
        Files.writeString(sources.resolve("com/acme/Status.java"), ORIGINAL);
        Files.writeString(copies.resolve("com/acme/Status.java"), DELOMBOKED);
        // An original that does not parse
        Files.writeString(sources.resolve("com/acme/Broken.java"), "package com.acme; public class Broken {");
        Files.writeString(copies.resolve("com/acme/Broken.java"), "package com.acme;\npublic class Broken {\n}\n");

        assertArrayEquals(new int[]{1, 1}, LombokMembers.mergeAll(sources, copies));
        assertTrue(Files.readString(copies.resolve("com/acme/Status.java")).contains("private boolean connected = false;"));
        assertEquals("package com.acme;\npublic class Broken {\n}\n", Files.readString(copies.resolve("com/acme/Broken.java")));
        assertEquals(Optional.empty(), LombokMembers.merge("class A {", DELOMBOKED));
    }
}
